self.KB_CONTENT["card:779107"]={"id":"card:779107","ty":"card","sourceId":"779107","title":"『暫出/入歸還建立作業(IDL)』中的『總數量 (TH021)』為何？","ver":"GP4以上","topic":"暫出入","keywords":["暫出入","單身","單位","製造"],"y":"other","answer":"* 此欄位僅作顯示。* 累計單身數量。* 數量表達方式為「單一單位」或「製造雙單位」時，加總單身數量。* 數量表達方式為「雙單位」時，加總單身數量的整數部份。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
