self.KB_CONTENT["card:777138"]={"id":"card:777138","ty":"card","sourceId":"777138","title":"『多角貿易計價及轉撥單價建立作業』中的『序號 (TB006)』為何？","ver":"GP4以上","topic":"多角貿易","keywords":["多角貿易","單身","序號","單價"],"y":"other","answer":"* 系統自動預設，序號由 0001 開始起編。『：子單身』(icon)","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
